WITH , latest AS ( SELECT DISTINCT ON (u.wizard_id) u.wizard_id, u.wizard_name, u.country_code AS country, u.channel_uid, CAST(TRIM(u.ladder_score::text) AS INT) AS score, CASE WHEN TRIM(COALESCE(u.rating_id::text, '')) ~ '^[0-9]+$' THEN CAST(TRIM(u.rating_id::text) AS INT) ELSE NULL END AS rating_id, r.date_add AS last_match_at FROM public.rta_match_participant u INNER JOIN rta_match_in_season r ON u.replay_id = r.rid WHERE TRIM(COALESCE(u.ladder_score::text, '')) ~ '^[0-9]+$' AND CAST(TRIM(u.ladder_score::text) AS INT) > 0 ORDER BY u.wizard_id, r.date_add DESC ), ranked AS ( SELECT latest.wizard_id, latest.wizard_name, latest.country, latest.channel_uid, latest.score, latest.rating_id, latest.last_match_at, ROW_NUMBER() OVER (ORDER BY latest.score DESC, latest.wizard_id ASC) AS rank_position FROM latest ), ranked_filtered AS ( SELECT r.* FROM ranked r WHERE 1 = 1
AND ( CASE WHEN TRIM(COALESCE(r.country::text, '')) = '' THEN '—' ELSE TRIM(r.country::text) END ) = #{countryFilter}
) SELECT COUNT(*)::int FROM ranked_filtered

WITH , , latest AS ( SELECT DISTINCT ON (u.wizard_id) u.wizard_id, u.wizard_name, u.country_code AS country, u.channel_uid, CAST(TRIM(u.ladder_score::text) AS INT) AS score, CASE WHEN TRIM(COALESCE(u.rating_id::text, '')) ~ '^[0-9]+$' THEN CAST(TRIM(u.rating_id::text) AS INT) ELSE NULL END AS rating_id, r.date_add AS last_match_at FROM public.rta_match_participant u INNER JOIN rta_match_in_season r ON u.replay_id = r.rid WHERE TRIM(COALESCE(u.ladder_score::text, '')) ~ '^[0-9]+$' AND CAST(TRIM(u.ladder_score::text) AS INT) > 0 ORDER BY u.wizard_id, r.date_add DESC ), ranked AS ( SELECT latest.wizard_id, latest.wizard_name, latest.country, latest.channel_uid, latest.score, latest.rating_id, latest.last_match_at, ROW_NUMBER() OVER (ORDER BY latest.score DESC, latest.wizard_id ASC) AS rank_position FROM latest ), ranked_filtered AS ( SELECT r.* FROM ranked r WHERE 1 = 1
AND ( CASE WHEN TRIM(COALESCE(r.country::text, '')) = '' THEN '—' ELSE TRIM(r.country::text) END ) = #{countryFilter}
), score_max_agg AS ( SELECT u.wizard_id, MAX(CAST(TRIM(u.ladder_score::text) AS INT))::int AS max_season_score FROM public.rta_match_participant u INNER JOIN rta_match_in_season r ON u.replay_id = r.rid WHERE TRIM(COALESCE(u.ladder_score::text, '')) ~ '^[0-9]+$' AND CAST(TRIM(u.ladder_score::text) AS INT) > 0 GROUP BY u.wizard_id ), page_ranked AS ( SELECT * FROM ranked_filtered ORDER BY rank_position LIMIT #{limit} OFFSET #{offset} ), field_pick_counts AS ( SELECT u.wizard_id, TRIM(BOTH FROM u.unit_master_id::text) AS unit_master_id, COUNT(*)::bigint AS pick_count FROM public.rta_match_unit_pick u WHERE TRIM(BOTH FROM COALESCE(u.unit_master_id::text, '')) ~ '^[0-9]+$' AND NOT u.is_banned AND u.wizard_id IN (SELECT wizard_id FROM page_ranked) GROUP BY u.wizard_id, TRIM(BOTH FROM u.unit_master_id::text) ), ranked_monsters AS ( SELECT wizard_id, unit_master_id, pick_count, ROW_NUMBER() OVER ( PARTITION BY wizard_id ORDER BY pick_count DESC, CAST(unit_master_id AS BIGINT) ASC ) AS rn FROM field_pick_counts ), most1 AS ( SELECT wizard_id, unit_master_id AS m1_id, pick_count AS m1_pick FROM ranked_monsters WHERE rn = 1 ), most2 AS ( SELECT wizard_id, unit_master_id AS m2_id, pick_count AS m2_pick FROM ranked_monsters WHERE rn = 2 ), most3 AS ( SELECT wizard_id, unit_master_id AS m3_id, pick_count AS m3_pick FROM ranked_monsters WHERE rn = 3 ) SELECT pr.rank_position, pr.wizard_id, pr.wizard_name, pr.country, pr.channel_uid, pr.score, pr.rating_id, pr.last_match_at, COALESCE(wa.match_count, 0)::bigint AS match_count, COALESCE(wa.win_count, 0)::bigint AS win_count, COALESCE(sm.max_season_score, pr.score)::int AS max_season_score, m1.m1_id::text AS most_monster_1_id, m1.m1_pick AS most_monster_1_pick_count, COALESCE(mm1.kr_name, '') AS most_monster_1_name, CASE WHEN mm1.kr_name IS NOT NULL THEN '/images/' || mm1.monster_elemental || '/' || replace(mm1.kr_name, ' ', '_') || '_' || mm1.monster_elemental || '_Icon.png' ELSE '' END AS most_monster_1_image, m2.m2_id::text AS most_monster_2_id, m2.m2_pick AS most_monster_2_pick_count, COALESCE(mm2.kr_name, '') AS most_monster_2_name, CASE WHEN mm2.kr_name IS NOT NULL THEN '/images/' || mm2.monster_elemental || '/' || replace(mm2.kr_name, ' ', '_') || '_' || mm2.monster_elemental || '_Icon.png' ELSE '' END AS most_monster_2_image, m3.m3_id::text AS most_monster_3_id, m3.m3_pick AS most_monster_3_pick_count, COALESCE(mm3.kr_name, '') AS most_monster_3_name, CASE WHEN mm3.kr_name IS NOT NULL THEN '/images/' || mm3.monster_elemental || '/' || replace(mm3.kr_name, ' ', '_') || '_' || mm3.monster_elemental || '_Icon.png' ELSE '' END AS most_monster_3_image FROM page_ranked pr LEFT JOIN win_agg wa ON pr.wizard_id = wa.wizard_id LEFT JOIN score_max_agg sm ON pr.wizard_id = sm.wizard_id LEFT JOIN most1 m1 ON pr.wizard_id = m1.wizard_id LEFT JOIN public.monster mm1 ON m1.m1_id IS NOT NULL AND TRIM(BOTH FROM m1.m1_id::text) ~ '^[0-9]+$' AND mm1.monster_id = TRIM(BOTH FROM m1.m1_id::text) LEFT JOIN most2 m2 ON pr.wizard_id = m2.wizard_id LEFT JOIN public.monster mm2 ON m2.m2_id IS NOT NULL AND TRIM(BOTH FROM m2.m2_id::text) ~ '^[0-9]+$' AND mm2.monster_id = TRIM(BOTH FROM m2.m2_id::text) LEFT JOIN most3 m3 ON pr.wizard_id = m3.wizard_id LEFT JOIN public.monster mm3 ON m3.m3_id IS NOT NULL AND TRIM(BOTH FROM m3.m3_id::text) ~ '^[0-9]+$' AND mm3.monster_id = TRIM(BOTH FROM m3.m3_id::text) ORDER BY pr.rank_position
